      await connection.query(`INSERT INTO movement_events(container_id,container_number,event_type,actor,reason,previous_values,new_values) VALUES (?,?,\'RECORD_UPDATED\',?,?,?,?)`,[old.id,updated.container_number,req.user.email,'Container record updated',JSON.stringify(old),JSON.stringify(updated)]);
      await connection.query('INSERT INTO audit_log(actor,role_name,action,entity_type,entity_id,reason,old_values,new_values) VALUES (?,?,?,?,?,?,?,?)',[req.user.email,req.user.role_name,'UPDATE','CONTAINER',String(old.id),'Container record updated',JSON.stringify(old),JSON.stringify(updated)]);
      const validation=Object.hasOwn(r,'container_number')?validateContainerNumber(updated.container_number):{};
      await connection.commit();res.json({id:updated.id,container_number:updated.container_number,warning:validation.warning||null});
