  app.put('/api/operational-rules/:code',requirePermission('master:manage'),async(req,res,next)=>{const {label,value,description,is_active=true}=req.body;if(!label||value===undefined)return res.status(400).json({error:'Rule label and value are required.'});try{await pool.query('INSERT INTO operational_rules(rule_code,label,value_json,description,is_active,updated_by) VALUES (?,?,?,?,?,?) ON DUPLICATE KEY UPDATE label=VALUES(label),value_json=VALUES(value_json),description=VALUES(description),is_active=VALUES(is_active),updated_by=VALUES(updated_by)',[req.params.code,label,JSON.stringify(value),description||null,is_active?1:0,req.user.email]);res.json({status:'updated'});}catch(error){next(error);}});
