  app.get('/api/reconciliation/discrepancies',reconciliationRead,async(req,res,next)=>{try{const status=String(req.query.status||'');const [rows]=await pool.query("SELECT * FROM reconciliation_discrepancies WHERE (?='' OR status=?) ORDER BY FIELD(status,'OPEN','RESOLVED','WAIVED'),detected_at DESC LIMIT 500",[status,status]);res.json(rows);}catch(error){next(error);}});
  app.post('/api/reconciliation/run',requirePermission('yard:plan'),async(req,res,next)=>{const connection=await pool.getConnection();try{await connection.beginTransaction();const [issues]=await connection.query(`SELECT c.id container_id,c.container_number,'LOCATION_POINTER_MISMATCH' category,CONCAT('Container points to ',COALESCE(l.location_code,'missing slot'),' but the slot does not confirm this container.') description FROM containers c LEFT JOIN yard_locations l ON l.id=c.current_location_id WHERE c.current_location_id IS NOT NULL AND c.status<>'GATED_OUT' AND (l.id IS NULL OR l.occupied_container_id IS NULL OR l.occupied_container_id<>c.id) UNION SELECT c.id,c.container_number,'SLOT_POINTER_MISMATCH',CONCAT('Slot ',l.location_code,' points to this container while its confirmed location differs.') FROM yard_locations l JOIN containers c ON c.id=l.occupied_container_id WHERE c.current_location_id IS NULL OR c.current_location_id<>l.id`);let opened=0;for(const issue of issues){const [[existing]]=await connection.query("SELECT id FROM reconciliation_discrepancies WHERE container_id=? AND category=? AND status='OPEN' LIMIT 1 FOR UPDATE",[issue.container_id,issue.category]);if(!existing){await connection.query('INSERT INTO reconciliation_discrepancies(container_id,container_number,category,description) VALUES (?,?,?,?)',[issue.container_id,issue.container_number,issue.category,issue.description]);opened++;}}const [openRows]=await connection.query("SELECT * FROM reconciliation_discrepancies WHERE status='OPEN' ORDER BY detected_at DESC");await connection.query('INSERT INTO audit_log(actor,role_name,action,entity_type,entity_id,new_values) VALUES (?,?,?,?,?,?)',[req.user.email,req.user.role_name,'RECONCILIATION_RUN','RECONCILIATION',null,JSON.stringify({opened,open_count:openRows.length})]);await connection.commit();res.json({opened,open_count:openRows.length,items:openRows});}catch(error){await connection.rollback();next(error);}finally{connection.release();}});
  app.patch('/api/reconciliation/discrepancies/:id/resolve',requirePermission('yard:plan'),async(req,res,next)=>{const reason=String(req.body.reason||'').trim();if(!reason)return res.status(400).json({error:'Resolution reason is required.'});try{const [r]=await pool.query("UPDATE reconciliation_discrepancies SET status='RESOLVED',resolved_at=NOW(),resolved_by=?,description=CONCAT(description,' Resolution: ',?) WHERE id=? AND status='OPEN'",[req.user.email,reason,req.params.id]);if(!r.affectedRows)return res.status(404).json({error:'Open discrepancy not found.'});await pool.query('INSERT INTO audit_log(actor,role_name,action,entity_type,entity_id,reason) VALUES (?,?,?,?,?,?)',[req.user.email,req.user.role_name,'RECONCILIATION_RESOLVE','RECONCILIATION',String(req.params.id),reason]);res.json({status:'RESOLVED'});}catch(error){next(error);}});
